"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[39812],{39812:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/such-unexpected-neuroscience.png\\"\\n          title=\\"Seven and a Half Lessons About the Brain\\"\\n          author=\\"Lisa Feldman Barrett\\"\\n          publisher=\\"The Quest\\"\\n          publishedDate=\\"2021-08-05\\"\\n          isbn=\\"9791165215842\\"\\n          rating=4.5\\n          tags=\\"science\\"\\n        />\\n</center>\\n\\n## Review\\n<mark>Your brain does not exist to think</mark>.  \\nThis seems to be the most shocking and core content of this book.  \\n<br>\\nThe most important task of the brain is not thinking, but ```allostasis```, which is efficiently managing the body budget.  \\nUltimately, the brain did not evolve to think, but evolved to predict, distribute, and balance the energy the body will use in a constantly changing environment.\\n<br>\\nFrom this perspective, we must understand the brain anew.  \\n<br>\\n1. The brain does not ```see``` the world, but ```predicts``` and ```constructs``` it.\\n2. Emotions are not triggered, but are ```made``` by the brain.\\n3. The ```triune brain``` is a myth: there is no reptile brain.\\n<br>\\nI should read it carefully again when I have the chance.  "}')}}]);